const listMemberDirectory = `-- name: ListMemberDirectory :many
SELECT m.id, m.display_name, m.email, (m.user_id IS NOT NULL)::boolean AS has_linked_user
FROM org.member m
WHERE m.company_id = $1 AND m.is_active = true
  AND ($4::text IS NULL
       OR m.display_name ILIKE '%' || $4::text || '%' ESCAPE '\'
       OR m.email ILIKE '%' || $4::text || '%' ESCAPE '\')
ORDER BY m.display_name
LIMIT $2 OFFSET $3
`

type ListMemberDirectoryParams struct {
	CompanyID pgtype.UUID `json:"company_id"`
	Limit     int32       `json:"limit"`
	Offset    int32       `json:"offset"`
	Q         *string     `json:"q"`
}

type ListMemberDirectoryRow struct {
	ID            pgtype.UUID `json:"id"`
	DisplayName   string      `json:"display_name"`
	Email         *string     `json:"email"`
	HasLinkedUser bool        `json:"has_linked_user"`
}

// The browser-reachable member directory (share-with/assign-to picker). REDUCED view
// (id/displayName/email/hasLinkedUser only — least disclosure) over ACTIVE members of one
// company, optional case-insensitive LITERAL substring filter on displayName/email (sqlc.narg —
// NULL means "no filter"; the store escapes `\`, `%`, `_` in q, hence ESCAPE '\'),
// filtered/sorted/paginated entirely in SQL.
func (q *Queries) ListMemberDirectory(ctx context.Context, arg ListMemberDirectoryParams) ([]ListMemberDirectoryRow, error) {
	rows, err := q.db.Query(ctx, listMemberDirectory,
		arg.CompanyID,
		arg.Limit,
		arg.Offset,
		arg.Q,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListMemberDirectoryRow
	for rows.Next() {
		var i ListMemberDirectoryRow
		if err := rows.Scan(
			&i.ID,
			&i.DisplayName,
			&i.Email,
			&i.HasLinkedUser,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

