const listPositionsWithHolder = `-- name: ListPositionsWithHolder :many
SELECT p.id, p.company_id, p.code, p.title, p.org_unit_id,
       a.id AS assignment_id, a.member_id AS assignment_member_id,
       mem.display_name AS holder_display_name
FROM org.position p
LEFT JOIN org.position_assignment a
       ON a.position_id = p.id
      AND a.valid_from <= $4::date
      AND (a.valid_to IS NULL OR a.valid_to > $4::date)
LEFT JOIN org.member mem ON mem.id = a.member_id
WHERE p.company_id = $1
ORDER BY p.code
LIMIT $2 OFFSET $3
`

type ListPositionsWithHolderParams struct {
	CompanyID pgtype.UUID `json:"company_id"`
	Limit     int32       `json:"limit"`
	Offset    int32       `json:"offset"`
	Today     pgtype.Date `json:"today"`
}

type ListPositionsWithHolderRow struct {
	ID                 pgtype.UUID `json:"id"`
	CompanyID          pgtype.UUID `json:"company_id"`
	Code               string      `json:"code"`
	Title              string      `json:"title"`
	OrgUnitID          pgtype.UUID `json:"org_unit_id"`
	AssignmentID       pgtype.UUID `json:"assignment_id"`
	AssignmentMemberID pgtype.UUID `json:"assignment_member_id"`
	HolderDisplayName  *string     `json:"holder_display_name"`
}

// The admin list surface — each row carries the CURRENT assignment (assignmentId/memberId/
// holder displayName), the fields the UI needs to END a tenure. "current" = today's half-open
// window (migrations/org/0009): valid_from <= today AND
// (valid_to IS NULL OR valid_to > today). today is the store's tenant-timezone date (the same
// clock assign-NOW/end-NOW stamp), never CURRENT_DATE (the DB session's zone — a second clock).
// LEFT JOINs so an unassigned position still returns a row with NULL assignment fields, never
// omitted.
func (q *Queries) ListPositionsWithHolder(ctx context.Context, arg ListPositionsWithHolderParams) ([]ListPositionsWithHolderRow, error) {
	rows, err := q.db.Query(ctx, listPositionsWithHolder,
		arg.CompanyID,
		arg.Limit,
		arg.Offset,
		arg.Today,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListPositionsWithHolderRow
	for rows.Next() {
		var i ListPositionsWithHolderRow
		if err := rows.Scan(
			&i.ID,
			&i.CompanyID,
			&i.Code,
			&i.Title,
			&i.OrgUnitID,
			&i.AssignmentID,
			&i.AssignmentMemberID,
			&i.HolderDisplayName,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

