const subtreeOrgUnits = `-- name: SubtreeOrgUnits :many
WITH RECURSIVE subtree AS (
    SELECT r.id, r.type_key, r.parent_id, r.code, r.name, r.is_active, 0 AS depth
    FROM org.org_unit r
    WHERE r.id = $1
    UNION ALL
    SELECT u.id, u.type_key, u.parent_id, u.code, u.name, u.is_active, s.depth + 1
    FROM org.org_unit u
    JOIN subtree s ON u.parent_id = s.id
    WHERE s.depth < 32
)
SELECT subtree.id, subtree.type_key, subtree.parent_id, subtree.code, subtree.name, subtree.is_active, subtree.depth
FROM subtree ORDER BY depth, code
`

type SubtreeOrgUnitsRow struct {
	ID       pgtype.UUID `json:"id"`
	TypeKey  string      `json:"type_key"`
	ParentID pgtype.UUID `json:"parent_id"`
	Code     string      `json:"code"`
	Name     string      `json:"name"`
	IsActive bool        `json:"is_active"`
	Depth    int32       `json:"depth"`
}

// Recursive CTE, depth-bounded 32. Powers GET /internal/org/units/{id}/subtree and the
// cycle-proof parent-change validation (a candidate new parent must not already be in the
// moved unit's own subtree).
func (q *Queries) SubtreeOrgUnits(ctx context.Context, id pgtype.UUID) ([]SubtreeOrgUnitsRow, error) {
	rows, err := q.db.Query(ctx, subtreeOrgUnits, id)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []SubtreeOrgUnitsRow
	for rows.Next() {
		var i SubtreeOrgUnitsRow
		if err := rows.Scan(
			&i.ID,
			&i.TypeKey,
			&i.ParentID,
			&i.Code,
			&i.Name,
			&i.IsActive,
			&i.Depth,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

